{"implementation":"def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    edges = []
    for a, b, d in distances:
        if a < b:
            u, v = a, b
        else:
            u, v = b, a
        mrd = max(core[u], core[v], d)
        edges.append((mrd, u, v))
    edges.sort()
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    for mrd, u, v in edges:
        if len(selected) == n-1:
            break
        if union(u, v):
            selected.append([u, v, mrd])
            total += mrd
    if len(selected) != n-1:
        return {'error': 'disconnected graph'}
    return {'edges': selected, 'total_weight': total}"}
